// generated by pi-agent / gemini-3.8-flash
import React from 'react';
import { render, screen, userEvent, waitFor, cleanup } from '@testing-library/react-native';
import { Alert } from 'react-native';
import ResetPasswordScreen from '@/app/(auth)/reset-password';
import { supabase } from '@/lib/supabase';
import { useRouter } from 'expo-router';
import { useAuth } from '@/context/AuthContext';

describe('ResetPasswordScreen', () => {
  const mockReplace = jest.fn();
  const mockSetIsRecovering = jest.fn();
  const mockSignOut = jest.fn().mockResolvedValue(undefined);
  const alertSpy = jest.spyOn(Alert, 'alert');

  beforeEach(() => {
    jest.clearAllMocks();
    (useRouter as jest.Mock).mockReturnValue({
      replace: mockReplace,
      push: jest.fn(),
      back: jest.fn(),
      canGoBack: jest.fn(() => true),
    });
    (useAuth as jest.Mock).mockReturnValue({
      setIsRecovering: mockSetIsRecovering,
      signOut: mockSignOut,
    });
  });

  afterEach(async () => {
    await cleanup();
  });

  it('renders title, inputs, and action buttons', async () => {
    await render(<ResetPasswordScreen />);

    expect(screen.getByText('Set new password')).toBeTruthy();
    expect(screen.getByPlaceholderText('New password')).toBeTruthy();
    expect(screen.getByPlaceholderText('Confirm new password')).toBeTruthy();
    expect(screen.getByText('Update password')).toBeTruthy();
    expect(screen.getByLabelText('Cancel password reset')).toBeTruthy();
  });

  it('toggles password visibility for both password inputs', async () => {
    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    const newPassInput = screen.getByPlaceholderText('New password');
    const confirmPassInput = screen.getByPlaceholderText('Confirm new password');

    expect(newPassInput.props.secureTextEntry).toBe(true);
    expect(confirmPassInput.props.secureTextEntry).toBe(true);

    await user.press(screen.getByLabelText('Show password'));

    expect(screen.getByPlaceholderText('New password').props.secureTextEntry).toBe(false);
    expect(screen.getByPlaceholderText('Confirm new password').props.secureTextEntry).toBe(false);
    expect(screen.getByLabelText('Hide password')).toBeTruthy();
  });

  it('alerts error if password is shorter than 8 characters or missing letters/numbers', async () => {
    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    // Short password
    await user.type(screen.getByPlaceholderText('New password'), 'short1');
    await user.type(screen.getByPlaceholderText('Confirm new password'), 'short1');
    await user.press(screen.getByText('Update password'));

    expect(alertSpy).toHaveBeenCalledWith(
      'Invalid Password',
      'Password must be at least 8 characters with both letters and numbers.',
    );
    expect(supabase.auth.updateUser).not.toHaveBeenCalled();

    // No numbers
    alertSpy.mockClear();
    await user.clear(screen.getByPlaceholderText('New password'));
    await user.clear(screen.getByPlaceholderText('Confirm new password'));
    await user.type(screen.getByPlaceholderText('New password'), 'onlyletters');
    await user.type(screen.getByPlaceholderText('Confirm new password'), 'onlyletters');
    await user.press(screen.getByText('Update password'));

    expect(alertSpy).toHaveBeenCalledWith(
      'Invalid Password',
      'Password must be at least 8 characters with both letters and numbers.',
    );
  });

  it('alerts error if passwords do not match', async () => {
    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    await user.type(screen.getByPlaceholderText('New password'), 'ValidPass123');
    await user.type(screen.getByPlaceholderText('Confirm new password'), 'MismatchPass123');
    await user.press(screen.getByText('Update password'));

    expect(alertSpy).toHaveBeenCalledWith('Mismatch', 'Passwords do not match.');
    expect(supabase.auth.updateUser).not.toHaveBeenCalled();
  });

  it('handles update failure from supabase', async () => {
    (supabase.auth.updateUser as jest.Mock).mockResolvedValueOnce({
      error: { message: 'Auth session expired' },
    });

    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    await user.type(screen.getByPlaceholderText('New password'), 'NewPassword123');
    await user.type(screen.getByPlaceholderText('Confirm new password'), 'NewPassword123');
    await user.press(screen.getByText('Update password'));

    await waitFor(() => {
      expect(supabase.auth.updateUser).toHaveBeenCalledWith({
        password: 'NewPassword123',
      });
      expect(alertSpy).toHaveBeenCalledWith('Update failed', 'Auth session expired');
    });
  });

  it('successfully updates password, clears recovering mode, and navigates to tabs', async () => {
    (supabase.auth.updateUser as jest.Mock).mockResolvedValueOnce({
      error: null,
    });

    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    await user.type(screen.getByPlaceholderText('New password'), 'FreshPassword123');
    await user.type(screen.getByPlaceholderText('Confirm new password'), 'FreshPassword123');
    await user.press(screen.getByText('Update password'));

    await waitFor(() => {
      expect(mockSetIsRecovering).toHaveBeenCalledWith(false);
      expect(alertSpy).toHaveBeenCalledWith(
        'Success',
        'Your password has been updated.',
        expect.any(Array),
      );
    });

    const alertButtons = alertSpy.mock.calls[0][2];
    const continueButton = alertButtons?.find((btn) => btn.text === 'Continue');
    expect(continueButton).toBeDefined();
    continueButton?.onPress?.();

    expect(mockReplace).toHaveBeenCalledWith('/(tabs)');
  });

  it('signs out and navigates to login when cancel button is pressed', async () => {
    const user = userEvent.setup();
    await render(<ResetPasswordScreen />);

    await user.press(screen.getByLabelText('Cancel password reset'));

    expect(mockSignOut).toHaveBeenCalled();
    expect(mockReplace).toHaveBeenCalledWith('/(auth)/login');
  });

  it('signs out if the screen is unmounted without completing reset', async () => {
    const { unmount } = await render(<ResetPasswordScreen />);

    expect(mockSignOut).not.toHaveBeenCalled();

    await unmount();

    expect(mockSignOut).toHaveBeenCalled();
  });
});
